-- ============================================================================
-- 文件名称：erp_menu.sql
-- 用    途：制造企业 ERP（基于 RuoYi 3.9.2）菜单与权限初始化脚本
-- 内容说明：
--   1. 初始化 10 个业务目录（menu_type=M），挂载于顶级（parent_id=0）；
--   2. 每个目录下挂载对应业务菜单（menu_type=C）；
--   3. 每个菜单下挂载 5 个操作按钮（menu_type=F）：查询/新增/修改/删除/导出；
--   4. menu_id 固定占用 3000~3999 区间，脚本可重复执行（先清理再插入）；
--   5. 权限标识格式：<module>:<perm>:<action>，action ∈ {list,query,add,edit,remove,export}；
--   6. admin（role_id=1）为超级管理员，默认拥有全部菜单，无需插入 sys_role_menu；
--   7. 文件末尾将 3000~3999 的全部菜单授权给普通角色 role_id=2（该角色不存在时影响 0 行，可接受）。
-- 执行环境：MySQL 5.7+ / 8.0
-- 备注：sys_menu 实际表结构不含 is_default 字段，故本脚本未写入该列。
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. 清理旧的初始化数据（保证脚本可重复执行）
-- ----------------------------------------------------------------------------
delete from sys_menu where menu_id between 3000 and 3999;

-- ----------------------------------------------------------------------------
-- 2. 目录（menu_type=M，parent_id=0，is_frame=1）
-- ----------------------------------------------------------------------------

-- ----------------------------------------------------------------------------
-- 3. 菜单（menu_type=C，component=<module>/<route>/index，perms=<module>:<perm>:list）
-- ----------------------------------------------------------------------------
-- 3.1 基础平台 platform（parent_id=3000）

-- 3.2 主数据 mdm（parent_id=3001）

-- 3.3 销售管理 sales（parent_id=3002）

-- 3.4 采购管理 purchase（parent_id=3003）

-- 3.5 库存管理 inventory（parent_id=3004）

-- 3.6 计划管理 plan（parent_id=3005）

-- 3.7 生产制造 manufacturing（parent_id=3006）

-- 3.8 质量管理 quality（parent_id=3007）

-- 3.9 财务业务 finance（parent_id=3008）

-- 3.10 报表分析 bi（parent_id=3009）

-- ----------------------------------------------------------------------------
-- 4. 按钮（menu_type=F，path='' component='' visible='0' status='0'）
--    每个菜单 5 个按钮：查询(query)/新增(add)/修改(edit)/删除(remove)/导出(export)
-- ----------------------------------------------------------------------------
-- 4.1 基础平台 platform

-- 4.2 主数据 mdm

-- 4.3 销售管理 sales

-- 4.4 采购管理 purchase

-- 4.5 库存管理 inventory

-- 4.6 计划管理 plan

-- 4.7 生产制造 manufacturing

-- 4.8 质量管理 quality

-- 4.9 财务业务 finance

-- 4.10 报表分析 bi

-- ----------------------------------------------------------------------------
-- 5. 角色授权：将上述全部菜单（3000~3399）授权给普通角色 role_id=2
--    admin（role_id=1）为超级管理员，默认拥有全部菜单，无需插入。
--    若 role_id=2 角色不存在，本语句影响 0 行，属预期结果。
-- ----------------------------------------------------------------------------
